import type { ShopBrand, ShopProduct, ShopTag } from "./shop";

// More of the live catalogue (owner, 15 Oct 2026: 20 more men's jackets, 20
// more men's hoodies and sweats, and the women's shop brought close to the
// men's, from other shops than GOAT too). These pieces are from Stadium
// Goods, the New York sneaker and streetwear shop, read from its own store
// on 15 Oct 2026: names, colourways and style codes as it lists them, its
// price in US dollars for a new one in stock (the lowest across sizes), the
// sizes in stock, and its own photos. Generated; edit by hand if a piece
// sells out.

const SG = "https://www.stadiumgoods.com/products/";
/** A Stadium Goods photo, sized for the shop */
const sgPhoto = (url: string) => `${url}?width=900`;
const sg = (handle: string, brand: string, name: string, colour: string, category: ShopProduct["category"], kind: string, gender: "men" | "women" | "unisex", price: number, sizeLabel: string, sizes: string, front: string, back: string | undefined, tags: ShopTag[], specs: [string, string][]): ShopProduct => ({
  id: `sg-${handle}`, brand, name, colour, category, kind, gender, price, sizeLabel, sizes: sizes.split("|"), image: sgPhoto(front), ...(back ? { back: sgPhoto(back) } : {}),
  stage: "white", credit: "Photo: Stadium Goods", photoPage: SG + handle, retailer: "stadium-goods", url: SG + handle, tags, specs,
});

const WF = "https://www.watchfinder.com/watches/";
/** A Watchfinder & Co. photo, sized for the shop */
const wfPhoto = (url: string) => `${url}?quality=80&bg-color=255,255,255&fit=bounds&height=720&width=576`;
const wfl = (id: string, brand: string, name: string, colour: string, price: number, note: string, caseSize: string | undefined, front: string, back: string | undefined, path: string, specs: [string, string][]): ShopProduct => ({
  id, brand, name, colour, category: "Accessories", kind: "Watches", gender: "women", note, price, image: wfPhoto(front), ...(back ? { back: wfPhoto(back) } : {}), stage: "white", credit: "Photo: Watchfinder & Co.",
  photoPage: WF + path, retailer: "watchfinder", url: WF + path, tags: [], ...(caseSize ? { sizeLabel: "Case", sizes: [caseSize] } : {}), specs,
});

